import Foundation
import Testing
@testable import WeftMateCore

#if os(macOS)
/// Real HTTP through PersonalClient, with the production RSA/AES envelope generated by Node.
@Suite(.serialized) @MainActor struct PhoneSyncTests {
    @Test func readinessIsIndependentOfModelAndEmptyCopy() async throws {
        let f=try await PhoneSyncFixture();defer { f.close() }
        try await f.configure(["ready":false])
        try await f.sync()
        #expect(f.engine.state.snapshot?.model == nil)
        #expect(f.engine.state.snapshot?.items.isEmpty == true)
        try f.enqueue(1)
        try await f.sync()
        #expect(try await f.submissions().isEmpty)
        try await f.configure(["ready":true]);try await f.sync()
        let requests=try await f.submissions()
        #expect(requests.count == 1 && f.engine.state.synced.count == 1)
        #expect(requests[0]["handover"] != nil)
        let original=(requests[0]["turns"] as! [[String:Any]])[0]
        #expect(original["timestamp"] as? Int64 == 1_700_000_000_000)
        #expect((original["memoryRefs"] as! [[String:String]])[0]["id"] == "original-memory")
        #expect(original["dependencyComplete"] as? Bool == false)
        let report=try await f.report()
        #expect((report["sync"] as! [[String:Any]]).allSatisfy { $0["phoneFirst"] as? Bool == true })
    }
    @Test func drains51TurnsWithStableHandoverAndFinalFlag() async throws {
        let f=try await PhoneSyncFixture();defer { f.close() };try await f.sync();try f.enqueue(51)
        try await f.sync()
        let requests=try await f.submissions(),handovers=requests.map { $0["handover"] as! [String:Any] }
        #expect(requests.map { ($0["turns"] as! [Any]).count } == [50,1])
        #expect(handovers[0]["id"] as? String == handovers[1]["id"] as? String)
        #expect(handovers.allSatisfy { $0["totalTurns"] as? Int == 51 })
        #expect(handovers.map { $0["complete"] as! Bool } == [false,true])
        #expect(f.engine.state.synced.count == 51 && f.phone.threads.count == 51)
    }
    @Test func boundsEntireJSONIncludingEscapesAndMetadata() async throws {
        let f=try await PhoneSyncFixture();defer { f.close() };try await f.sync()
        let text=String(repeating:"\"\\\n茶😀/",count:1800)
        #expect(text.utf16.count <= 16384)
        #expect(try JSONEncoder().encode(text).count * 12 > 256*1024)
        try f.enqueue(12,text:text)
        try await f.sync()
        let report=try await f.report(),raw=report["raw"] as! [String]
        #expect(raw.count > 1)
        for text in raw { #expect(Data(base64Encoded:text)!.count <= 256*1024) }
        #expect(f.engine.state.synced.count == 12)
    }
    @Test func lostAndPartialReceiptsRestartWithIdenticalRequest() async throws {
        let f=try await PhoneSyncFixture();defer { f.close() };try await f.sync();try f.enqueue(3)
        let first=f.phone.migrations?[f.identity.hostId]?.handover
        try await f.configure(["lose":true])
        await #expect(throws:(any Error).self) { try await f.sync() }
        #expect(f.engine.state.synced.isEmpty)
        // Local edits and a new message cannot mutate this persisted cohort or its request.
        f.phone.threads[0].messages[1].text="重新生成的回复"
        var thread=PhoneChatThread();thread.messages=[.init(role:"user",text:"后来的新话")];f.phone.threads.append(thread)
        _ = f.phone.prepareMigration(host:f.identity.hostId,generation:1)
        #expect(f.phone.migrations?[f.identity.hostId]?.handover == first)
        f.engine=try OfflineReplica(vault:f.vault,phoneFirst:true)
        try await f.configure(["partial":true]);try await f.sync()
        #expect(f.engine.state.synced.count == 1)
        f.engine=try OfflineReplica(vault:f.vault,phoneFirst:true);try await f.sync()
        let raw=try await f.report()["raw"] as! [String]
        #expect(raw.count == 3 && Set(raw).count == 1)
        #expect(f.engine.state.synced.count == 3)
        f.phone.acknowledgeMigration(host:f.identity.hostId,generation:2,ids:f.engine.state.synced)
        #expect(f.phone.migrations?[f.identity.hostId]?.accepted.isEmpty == true)
        f.phone.acknowledgeMigration(host:f.identity.hostId,generation:1,ids:f.engine.state.synced)
        let next=f.phone.prepareMigration(host:f.identity.hostId,generation:1)
        #expect(next.count == 1 && next[0].messages[0].text == "后来的新话")
        #expect(f.phone.migrations?[f.identity.hostId]?.handover?.id != first?.id)
        #expect(f.phone.prepareMigration(host:"another-host",generation:1).isEmpty)
        let stored=try PhoneChatStore(account:"account-test",directory:f.directory.appendingPathComponent("Phone"),credentials:f.keys)
        try stored.save(f.phone)
        #expect(try stored.load().migrations?[f.identity.hostId]?.handover == f.phone.migrations?[f.identity.hostId]?.handover)
        let other=try PhoneChatStore(account:"other-account",directory:f.directory.appendingPathComponent("Phone"),credentials:f.keys)
        #expect(try other.load().threads.isEmpty)
        #expect(try Data(contentsOf:stored.file).range(of:Data("后来的新话".utf8)) == nil)
    }
    @Test func rejectsForeignReceiptsAndGenerationAndAuthorityHost() async throws {
        for fault in ["foreignReceipt","wrongGeneration","wrongAuthority","wrongControl","badReady"] {
            let f=try await PhoneSyncFixture();defer { f.close() };try await f.sync();try f.enqueue(1)
            try await f.configure([fault:true])
            await #expect(throws:(any Error).self) { try await f.sync() }
            #expect(f.engine.state.synced.isEmpty)
            if ["wrongAuthority","wrongControl","badReady"].contains(fault) { #expect(try await f.submissions().isEmpty) }
        }
    }
    @Test func missingAuthorityKeepsOriginalsWaiting() async throws {
        let f=try await PhoneSyncFixture();defer { f.close() };try await f.sync();try f.enqueue(1)
        try await f.configure(["missingAuthority":true]);try await f.sync()
        #expect(try await f.submissions().isEmpty)
        #expect(f.engine.state.turns.count == 1 && f.engine.state.synced.isEmpty)
    }
}

@MainActor final class PhoneSyncFixture {
    let process=Process()
    let directory=FileManager.default.temporaryDirectory.appendingPathComponent("phone-sync-"+UUID().uuidString)
    let keys=MemoryStore()
    let identity=OfflineIdentity(ownerId:"owner-test",hostId:"host-test",deviceId:"device-test")
    let vault: OfflineVault
    var engine: OfflineReplica
    let client: PersonalClient
    let origin: String
    var phone=PhoneChatState()
    init(sourceName: String = "phone_sync_server.mjs") async throws {
        vault=try OfflineVault(identity:identity,directory:directory,store:keys)
        engine=try OfflineReplica(vault:vault,phoneFirst:true)
        client=PersonalClient(credentialStore:keys)
        let pipe=Pipe()
        let source=URL(fileURLWithPath:#filePath).deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent("Tests/"+sourceName)
        process.executableURL=URL(fileURLWithPath:"/usr/bin/env");process.arguments=["node",source.path];process.standardOutput=pipe
        try process.run()
        var data=Data()
        while true { let byte=pipe.fileHandleForReading.readData(ofLength:1);guard !byte.isEmpty else { process.terminate();throw OfflineFailure.invalid };if byte == Data([10]) { break };data.append(byte) }
        origin=(try JSONSerialization.jsonObject(with:data) as! [String:String])["origin"]!
        do { _ = try await client.login(server:ServerConfiguration(input:origin,allowLoopbackHTTP:true),username:"synthetic",password:"synthetic-password",deviceName:"PhoneSync") }
        catch { close();throw error }
    }
    func close() { if process.isRunning { process.terminate();process.waitUntilExit() };try? FileManager.default.removeItem(at:directory) }
    func configure(_ value: [String:Any]) async throws {
        var request=URLRequest(url:URL(string:origin+"/configure")!);request.httpMethod="POST";request.httpBody=try JSONSerialization.data(withJSONObject:value)
        _ = try await URLSession.shared.data(for:request)
    }
    func report() async throws -> [String:Any] {
        let (data,_)=try await URLSession.shared.data(from:URL(string:origin+"/report")!)
        return try JSONSerialization.jsonObject(with:data) as! [String:Any]
    }
    func submissions() async throws -> [[String:Any]] { try await report()["turns"] as! [[String:Any]] }
    func sync() async throws {
        try await engine.sync(identity:identity,fetch:{ try await self.client.syncOffline($0) },submit:{ try await self.client.submitOffline($0) },control:{ _ in .init(hostId:"host-test",accountId:"account-test",generation:1,authorized:true) })
    }
    func enqueue(_ count: Int,text: String = "合成原话") throws {
        for _ in 0..<count {
            var thread=PhoneChatThread(),user=PhoneChatMessage(role:"user",text:text),reply=PhoneChatMessage(role:"assistant",text:"合成回复")
            user.date=Date(timeIntervalSince1970:1_700_000_000)
            reply.memoryRefs=[.init(kind:"cognition",id:"original-memory")];reply.dependencyComplete=false
            thread.messages=[user,reply];phone.threads.append(thread)
        }
        let turns=phone.prepareMigration(host:identity.hostId,generation:1)
        try engine.enqueuePhoneTurns(turns,generation:1,handover:phone.migrations?[identity.hostId]?.handover)
    }
}
#endif
